   "analysis": "本题考查法律常识。根据宪法及有关规定，全国行政编制的核定权和调整权属于国务院。在中央核定的编制总额内，中央各部门和地方各级党委、政府还要逐级分别核定和下达本系统、本区划内下一级具体地区相应的编制总额。核定编制总额一般只在机构改革或国家政治、经济、文化及社会发展发生较大变化时才实行。因此，ACD项不符合题意。\n故正确答案为B。",
