   "analysis": "海绵城市，是新一代城市雨洪管理概念，海绵城市是指通过加强城市规划建设管理，充分发挥建筑、道路和绿地、水系等生态系统对雨水的吸纳、蓄渗和缓释作用，有效控制雨水径流，实现自然积存、自然渗透、自然净化的城市发展方式。建设海绵城市就要有“海绵体”。“城市海绵体”既包括河、湖、池塘等水系，也包括绿地、花园、可渗透路面这样的城市配套设施。雨水通过这些“海绵体”下渗、滞蓄、净化、回用，最后剩余部分径流通过管网、泵站外排，从而可有效提高城市排水系统的标准，缓减城市内涝的压力。《国务院办公厅关于推进海绵城市建设的指导意见》中指出：推进海绵型道路与广场建设，在非机动车道、人行道、停车场、广场等扩大使用透水铺装，推行道路与广场雨水的收集、净化和利用，减轻对市政排水系统的压力。B项符合城市海绵体的要求。\nA项错误：没有提到可渗透路面这一重要的城市配套设施，且大型写字楼也无法体现排水功能。C、D项中的硬质柏油和水泥路面透水率低，不利于排解城市洪涝。\n故正确答案为B。",
   "exam": "tianjin",
   "year": 2017
