   "question": "某公安机关依据《治安管理处罚法》对甲某给予行政拘留的处罚，在处理该案中干警乙某违纪，被公安机关依据《中华人民共和国公务员法》给予开除处分，此案例中，可申请行政复议的是（    ）。",
   "options": [
    "A. 《治安管理处罚法》",
    "B. 行政拘留处罚",
    "C. 《中华人民共和国公务员法》",
    "D. 行政开除处分"
   ],
   "answer": "B",
   "analysis": "本题考查法律常识。\nA、C两项错误，《行政复议法》第十三条规定：“公民、法人或者其他组织认为行政机关的行政行为所依据的下列规范性文件不合法，在对行政行为申请行政复议时，可以一并向行政复议机关提出对该规范性文件的附带审查申请：（一）国务院部门的规范性文件；（二）县级以上地方各级人民政府及其工作部门的规范性文件；（三）乡、镇人民政府的规范性文件；（四）法律、法规、规章授权的组织的规范性文件。前款所列规范性文件不含规章。规章的审查依照法律、行政法规办理。”因此，行政复议可附带审查行政机关的具体行政行为所依据的规范性文件，但仅限定为《行政复议法》第十四条规定的范围。在本题中，《治安管理处罚法》和《中华人民共和国公务员法》都是法律，不能申请行政复议。\nB项正确，《行政复议法》第十一条第一项规定：“有下列情形之一的，公民、法人或者其他组织可以依照本法申请行政复议：（一）对行政机关作出的行政处罚决定不服；”在本案中，若甲不服公安机关对其作出的行政拘留的处罚，可申请行政复议。\nD项错误，《行政复议法》第十二条第三项规定：“下列事项不属于行政复议范围：（三）行政机关对行政机关工作人员的奖惩、任免等决定；”对干警乙作出的行政开除处分，干警乙可以对行政处分提出申诉，但不能申请行政复议。 \n故正确答案为B。",
   "exam": "tianjin",
   "year": 2017
