   "source": "2017年天津市选调生选拔考试 综合知识试卷 · 第18题",
   "question": "甲、乙二青年上山游玩，为寻求刺激甲欲将一圆木滚下山，乙表示同意，于是两人共同将此圆木从山上扔下，不料正好砸伤下山的路人丙，此事应由谁来承担民事责任？",
