   "source": "2018年421联考《行测》题（天津卷） · 第2题",
   "question": "小明在图书馆大声说话，有读者制止他时，他却说：“这是我的权利和自由，别人无权干涉”。关于上述观点的评价正确的是：\n①正确，宪法规定公民有言论自由\n②错误，公民的自由是在法律范围内的自由\n③错误，未经他人许可，公民不得擅自行使权利\n④错误，世界上从来没有“绝对”的权利和自由",
   "options": [
    "A. ①②",
    "B. ①③",
    "C. ②③",
    "D. ②④"
   ],
   "answer": "D",
   "analysis": "本题考查宪法的相关知识，主要考查权利和自由。\n①错误，我国《宪法》第三十五条规定：“中华人民共和国公民有言论、出版、集会、结社、游行、示威的自由。”有言论自由并不等于不分场所的随意行使自己的权利，图书馆属于公共场所，禁止大声喧哗。选项表述正确，但不符合题意。\n②正确，我国公民言论、出版、集会、结社、游行、示威的自由，都必须在国家法律、法规规定的范围内行使，自由是相对的，而不是绝对的，自由和法律是统一的，法律是自由的体现和保证，自由要受法律的制约。\n③错误，公民有行使自己权利的自由，不需要经过任何人同意，但是，前提是行使自己的权利不得触犯法律，不得损害他人利益。图书馆内禁止大声喧哗，小明在行使自己权利时损害了他人的利益。\n④正确，没有绝对的权利和自由，任何权利和自由都是有条件的，都是受到一定限制的。任何权利和自由都是在法律许可的范围内行使，否则就会受到法律的制裁。行使权利和自由不得损害他人的合法权益。小明在图书馆大声喧哗，损害了他人的利益。因此，世界上不存在“绝对”的权利和自由。\n①③错误，②④正确。\n故正确答案为D。",
   "exam": "tianjin",
   "year": 2018
