   "analysis": "本题考查科技常识。\n北斗卫星导航系统是我国自主建设、独立运行的全球卫星导航系统，将为全球用户提供全天候、全天时、高精度全球定位导航授时服务。\nA、D两项正确，1994年，我国正式启动北斗卫星导航系统建设。20多年来，探索适合国情的卫星导航系统发展道路，逐步形成了“三步走”发展战略：2000年年底，建成北斗一号系统，向中国提供服务；2012年年底，建成北斗二号系统，向亚太地区提供服务；2020年，建成北斗三号系统，向全球提供服务。\nB项错误，北斗卫星导航系统广泛开展国际合作，持续推动系统兼容共用。截至2019年年底，国产北斗导航型芯片模块出货量已超1亿片，季度出货量突破1000万片。北斗导航型芯片、模块、高精度板卡和天线已输出到100余个国家和地区。因此三分之一的国家明显低估。\nC项正确，2020年6月23日，我国在西昌卫星发射中心用长征三号乙运载火箭，成功发射北斗系统第五十五颗导航卫星，暨北斗三号最后一颗全球组网卫星，至此北斗三号全球卫星导航系统星座部署比原计划提前半年全面完成。\n本题为选非题，故正确答案为B。",
