   "source": "2020年天津市公务员考试《行测》试题 · 第16题",
   "question": "下列关于基因工程表述正确的是：",
   "options": [
    "A. 各种遗传病的基因异常是不同的，同一遗传病的基因异常是相同的",
    "B. 基因治疗就是把缺陷基因诱变成正常基因",
    "C. 基因诊断的基本原理就是DNA分子杂交",
    "D. 一种基因探针能检测水体中的各种病毒"
   ],
   "answer": "C",
   "analysis": "本题考查科技常识。\nA项错误，人类的遗传病主要可以分为单基因遗传病、多基因遗传病和染色体异常遗传病三大类，其中多基因遗传病中的任一个基因变异都可能会得遗传病，因此同一遗传病的基因变异可能是不同的。 \nB项错误，基因治疗是指用正常基因取代或修补病人细胞中有缺陷的基因，以纠正或补偿因基因缺陷和异常引起的疾病，达到治疗目的。\nC项正确，基因诊断的基本原理是DNA分子杂交，指用放射性同位素、荧光分子等标记的DNA分子做探针，利用DNA分子杂交原理，鉴定被检测样本上的遗传信息，从而达到检测疾病的目的。\nD项错误，基因探针是一段带有标记的，与待测基因有关的核酸序列，而各种病毒的核酸序列各不相同。因此一种基因探针只能检测水体中的一种病毒。\n故正确答案为C。",
   "exam": "tianjin",
   "year": 2020
