   "source": "2021年天津市公务员考试《行测》题 · 第5题",
   "question": "下列关于我国生态环境保护方面的说法不准确的是：",
   "options": [
    "A. 第二次全国污染源普查的结果显示，我国主要污染物排放量大幅下降",
    "B. 我国生态环境保护三大保卫战指的是蓝天保卫战、碧水保卫战和净土保卫战",
    "C. “无废城市”是一种先进的城市管理理念，实现了固体废物的完全资源化利用",
    "D. 新修订的《中华人民共和国森林法》自2020年7月1日起施行，此次修订将森林生态效益补偿写入了法律"
   ],
   "answer": "C",
   "analysis": "本题考查政治常识。\nA项正确，2020年6月10日，国务院新闻办举行发布会，生态环境部、国家统计局、农业农村部共同发布《第二次全国污染源普查公报》。生态环境部副部长赵英民在国务院新闻办当天举行的新闻发布会上指出，污染源整体情况有三方面的变化：一是主要污染物排放量大幅下降。与第一次全国污染源普查数据同口径相比，2017年二氧化硫、化学需氧量、氮氧化物等污染物排放量比2007年分别下降了img/formula-1e0a0992cd1f3d68.webp、img/formula-6b210c4a3fdf00b2.webp和img/formula-da72d095ea3e7883.webp。二是产业结构调整成效显著。三是污染治理能力明显提升。\nB项正确，2018年6月24日公布的《中共中央国务院关于全面加强生态环境保护坚决打好污染防治攻坚战的意见》提出，坚决打赢蓝天保卫战，着力打好碧水保卫战，扎实推进净土保卫战。\nC项错误，2019年1月21日，国务院办公厅发布了《“无废城市”建设试点工作方案》。指出，“无废城市”是以创新、协调、绿色、开放、共享的新发展理念为引领，通过推动形成绿色发展方式和生活方式，持续推进固体废物源头减量和资源化利用，最大限度减少填埋量，将固体废物环境影响降至最低的城市发展模式。“无废城市”并不是没有固体废物产生，也不意味着固体废物能完全资源化利用，而是一种先进的城市管理理念。\nD项正确，中华人民共和国第十三届全国人民代表大会常务委员会第十五次会议于2019年12月28日修订通过《中华人民共和国森林法》。新修订的《中华人民共和国森林法》自2020年7月1日起施行。新修订的《中华人民共和国森林法》第七条指出：“国家建立森林生态效益补偿制度，加大公益林保护支持力度，完善重点生态功能区转移支付政策，指导受益地区和森林生态保护地区人民政府通过协商等方式进行生态效益补偿。”\n本题为选非题，故正确答案为C。",
