   "analysis": "本题考查人文常识。\nA项错误，承德避暑山庄是中国古代帝王宫苑，清代皇帝避暑和处理政务的场所，始建于1703年，历经清康熙、雍正、乾隆三朝，耗时89年建成。\nB项错误，北京故宫是中国明清两代的皇家宫殿，旧称紫禁城，位于北京中轴线的中心。北京故宫于明成祖永乐四年（1406年）开始建设，以南京故宫为蓝本营建，到永乐十八年（1420年）建成，历经明、清两代，共有24个皇帝在此执政。\nC项错误，徽州古城分为内城和外廓，因为历史上古徽州县治与府治同在一座城内，所以呈现独特且典型的“城套城”风格。而平遥古城保存着最完整的古代县城格局风格，并非“城套城”风格。\nD项正确，孔林，亦称“至圣林”，是孔子及其家族的专用墓地，也是世界上延续时间最长的家族墓地；孔庙，由鲁哀公在孔子生前的故宅基础上改建而成的；孔府，即“衍圣公府”，在是孔子嫡系长子长孙居住的府地。孔府、孔庙、孔林统称曲阜“三孔”。\n故正确答案为D。",
   "exam": "tianjin",
