   "analysis": "本题考查科技常识。\nA、C、D三项错误，B项正确，球的飞行轨迹不仅受到自身重力的影响，还会受到来自空气的阻力的影响。我们通常会以为粗糙的球会受到更大的阻力，但这只考虑到了摩擦阻力，球在飞行中还受到一个压差阻力，也就是作用在球的前后的阻力，这个阻力比摩擦力的影响更大。球在飞行时，会产生“边界层效应”，如果表面粗糙，会在球的边界产生各种湍流，这些湍流都会影响球的飞行速度和线路。在球体飞行时，表面越是粗糙的球，受到的压差阻力反而越小，也因此粗糙的球会飞得更远。这一效应在球类运动上应用最明显的就是高尔夫球，在高尔夫球的表面，有很多规则的凹凸面，这些凹凸面是故意设计的，就是为了让球飞得更远。 \n故正确答案为B。",
