   "id": "xz-1f17pgp",
   "module": "常识判断",
   "source": "2024年天津市公务员录用考试《行测》题 · 第6题",
   "question": "唐代是丝绸之路的鼎盛时期，当时丝绸之路上的商队可能携带的商品是：",
   "options": [
    "A. 线装本的《史记》",
    "B. 精心制作的宣德炉",
    "C. 《司马温公神道碑》拓片",
    "D. 鎏金工艺制作的莲瓣银茶托"
   ],
   "answer": "D",
   "analysis": "本题考查人文常识。\nA项错误，线装书是指以线类进行装订的图书类型，又称古线装。中国古代的纸本书，经历了卷轴和册页两个阶段。卷轴由卷、轴、缥、带组装成。汉、唐代只有这种卷轴形式的书。宋代是书籍印刷爆发的时代，开始出现多种多样的装订方法，宋代是书籍装订形式最重要的一个时期，是书籍装订形式大发展时期与奠定时期，不仅蝴蝶装、包背装等明确产成在宋代，线装书也产成于宋代。唐代丝绸之路上的商队不可能携带线装本的《史记》。\nB项错误，宣德炉是由明宣宗朱瞻基在大明宣德三年参与设计监造的铜香炉，简称“宣炉”，是中国历史上第一次运用风磨铜铸成的铜器。唐代丝绸之路上的商队不可能携带精心制作的宣德炉。\nC项错误，《司马温公神道碑》是宋代苏轼五十三岁时奉宋哲宗之命为司马光撰写的碑文，碑文充满了苏轼对司马光的尊敬怀念之情。唐代丝绸之路上的商队不可能携带其拓片。\nD项正确，鎏金是一种金属加工工艺，始于战国，同时中国也是世界上最早使用这一技术的国家。1957年陕西省西安市唐长安城平康坊遗址出土了唐朝鎏金莲瓣银茶托，茶托盘底心下凹，周围有凸起托圈。唐代丝绸之路上的商队有可能携带鎏金工艺制作的莲瓣银茶托。\n故正确答案为D。",
   "exam": "tianjin",
   "year": 2024
