   "question": "2022年7月，美国宇航局（NASA）公布韦伯太空望远镜（JWST）拍摄的遥远气态星云一颗新生恒星的照片，其边缘区域的下半部尘埃和上半部气体形成的明显分界线，被天文学家称为“宇宙悬崖”。那么下列哪项最可能是“宇宙悬崖”的形成原因？",
