   "source": "2024年天津市公务员录用考试《行测》题 · 第16题",
   "question": "小明被困在一个无人、无食物来源但有淡水的荒岛上。假如他在等待救援期间可以从相同重量的葡萄、馒头、酸奶、花生仁这四种食物中选择一种，那么为了能在岛上生存的时间最长，他应该选择的食物是（    ）。",
   "options": [
    "A. 葡萄",
    "B. 馒头",
    "C. 酸奶",
    "D. 花生仁"
   ],
   "answer": "D",
   "analysis": "本题考查科技常识。\nA项错误，葡萄的主要成分是水分和糖类，每100克葡萄的热量约为45大卡。每100克葡萄中水分占到81克，碳水化合物为15.7克左右，蛋白质为0.7克，脂肪为0.6克，因此为了能在岛上生存的时间最长不适合选择葡萄。\nB项错误，馒头的主要成分是糖类，每100克馒头的热量约为230千卡。每100克馒头中碳水化合物的含量为47克，蛋白质为7克，脂肪为1.1克，因此为了能在岛上生存的时间最长不适合选择馒头。\nC项错误，酸奶是牛奶经过乳酸菌发酵而成，主要含有蛋白质、脂肪、乳酸菌、钙以及多种维生素，每100克酸奶的热量约为70大卡。每100克酸奶中的蛋白质含量为4.3克左右，脂肪为2.9克左右。因此为了能在岛上生存的时间最长不适合选择酸奶。\nD项正确，花生仁的主要成分是脂肪、蛋白质、碳水化合物，每100克花生仁的热量约为560大卡。每100克花生中蛋白质的含量为24.8克左右，脂肪为44.3克左右，碳水化合物为21.7克左右。相同重量的花生所含能量最多，因此为了能在岛上生存的时间最长应该选择花生仁。\n故正确答案为D。",
