   "question": "2024年是京津冀协同发展战略实施10周年，关于京津冀协同发展十年成果，下列表述正确的有几项？\n①天津的全国先进制造研发基地建设已进入快车道\n②京津冀三地以“六链五群”为协同发力点，加快产业成龙配套，成链成群\n③当前，京津冀三地产业已进入由疏解存量向共谋增量转变的阶段\n④天津“天鲸号”“天鲲号”刷新了海洋装备领域多项世界纪录",
