   "source": "2025年天津市公务员录用考试《行测》题 · 第6题",
   "question": "关于强制执行，下列说法错误的是：",
   "options": [
    "A. 强制执行一般由权利人提出申请，法院不会主动执行",
    "B. 强制执行措施包括查封、扣押、冻结、拍卖、变卖等",
    "C. 如果被执行人丧失了劳动能力，法院可以裁定终结执行",
    "D. 强制执行不仅限于财务，也可以要求当事人履行特定行为"
   ],
   "answer": "C",
   "analysis": "本题考查法律常识。\nA项正确，根据《中华人民共和国民事诉讼法》第二百四十七条第一款规定：“发生法律效力的民事判决、裁定，当事人必须履行。一方拒绝履行的，对方当事人可以向人民法院申请执行，也可以由审判员移送执行员执行。”因此，一般情况下，强制执行确需要权利人申请执行，法院不会主动执行；但也存在例外情况需由审判员移送执行员执行。\nB项正确，根据《中华人民共和国民事诉讼法》第二百五十五条第一款规定：“被执行人未按执行通知履行法律文书确定的义务，人民法院有权查封、扣押、冻结、拍卖、变卖被执行人应当履行义务部分的财产。但应当保留被执行人及其所扶养家属的生活必需品。”因此，人民法院的强制执行措施包括查封、扣押、冻结、拍卖、变卖等。\nC项错误，根据《中华人民共和国民事诉讼法》第二百六十八条第五项规定：“有下列情形之一的，人民法院裁定终结执行：（五）作为被执行人的公民因生活困难无力偿还借款，无收入来源，又丧失劳动能力的。”因此，被执行人除需要满足丧失了劳动能力这一条件以外，还需要满足生活困难无力偿还借款，无收入来源的条件，法院才可以裁定终结执行。\nD项正确，根据《中华人民共和国民事诉讼法》第二百五十五条第一款规定：“被执行人未按执行通知履行法律文书确定的义务，人民法院有权查封、扣押、冻结、拍卖、变卖被执行人应当履行义务部分的财产。但应当保留被执行人及其所扶养家属的生活必需品。”第二百六十一条第一款规定：“强制迁出房屋或者强制退出土地，由院长签发公告，责令被执行人在指定期间履行。被执行人逾期不履行的，由执行员强制执行。”因此，强制执行中除了查封、扣押、冻结、拍卖、变卖等涉及财产的执行方式外，还包括强制迁出房屋或者强制退出土地等涉及要求当事人履行特定行为的执行方式。\n本题为选非题，故正确答案为C。",
