   "source": "2026年天津市公务员录用考试《行测》题 · 第4题",
   "question": "若是太阳系的八大行星做自我介绍，下列不恰当的是：",
   "options": [
    "A. 天王星：我的大气层最为“高冷”，甲烷和氨让我赢得了冰巨星的“美誉”",
    "B. 海王星：直到今天，我还只是数学预测，人类的探测器从来没有看到过我",
    "C. 木星：在众多兄弟姐妹中我的“块头”最大，“黄白相间”是我的漂亮外衣",
    "D. 金星：“早东晚西”是我的位置特征，“启明”“长庚”是古人诗意的表达"
   ],
   "answer": "B",
   "analysis": "本题考查地理国情。\nA项正确，天王星属于冰巨星，其大气层以氢、氦为主要成分，其中甲烷会吸收太阳光中的红光波段，使其呈现淡蓝色外观。其云顶温度低至img/formula-c71d08b3a10ec5d3.webp，是太阳系中大气温度最低的行星，这一特征与它内部热源相对微弱有关，“高冷”的拟人化描述十分贴切。所谓“冰巨星”，是一类主要由内部大量存在的水、氨、甲烷等成分，在高温高压环境下形成的流体或热冰态物质（并非日常意义上的固态冰）构成的行星，其中，氨与甲烷均是冰巨星的核心特征成分。\nB项错误，海王星是在1846年根据勒威耶和亚当斯的数学预测而被发现的，故选项中“人类的探测器从来没有看到过我”的说法错误。1989年，美国宇航局（NASA）的旅行者2号探测器已成功飞掠海王星，进行了近距离探测并传回影像。\nC项正确，木星是太阳系中体积与质量最大的行星。其表面最显著的特征是平行于赤道的明暗相间云带（主要成分为氨冰晶体），常呈现黄、白、棕红等色调，故“黄白相间”是对其典型外观的生动概括。\nD项正确，金星是轨道位于地球轨道内侧的行星。从地球观测，它总在太阳附近摆动，时而作为“晨星”出现在东方黎明前（启明星），时而作为“昏星”出现在西方黄昏后（长庚星）。“早东晚西”准确概括了这一视觉规律。\n本题为选非题，故正确答案为B。",
   "exam": "tianjin",
