   "source": "2026年天津市公务员录用考试《行测》题 · 第5题",
   "question": "《汉书》中记载，宣帝作色曰：“汉家自有制度，本以霸王道杂之。奈何纯任德教，用周政乎！且俗儒不达时宜，好是古非今，使人眩於名实，不知所守，何足委任。”下列与之相关的说法正确的是：",
