   "source": "2026年天津市公务员录用考试《行测》题 · 第8题",
   "question": "青花瓷以其青白相间的优雅美感闻名于世。关于青花瓷的烧制过程，下列说法错误的是（    ）。",
   "options": [
    "A. 在高温阶段，瓷器胚体膨胀，而密度增加",
    "B. 窑炉通过热传递的方式改变瓷器胚体的内能",
    "C. 含有氧化钴的颜料在高温下会形成稳定的蓝色着色剂",
    "D. 青花瓷属于“釉下彩”，其图案需在瓷器烧制前进行绘制"
   ],
   "answer": "A",
   "analysis": "本题考查科技常识。\nA项错误，烧结是陶瓷生坯在高温下的致密化过程和现象的总称。随着温度的上升和时间的延长，固体颗粒相互键联，晶粒长大，空隙和晶界渐趋减少，通过物质的传递，其总体积收缩，密度增加，最后成为坚硬的只有某种显微结构的多晶烧结体，这种现象称为烧结。因此瓷器胚体是收缩而不是膨胀。\nB项正确，改变物体内能的核心方式包括做功和热传递。窑炉烧制瓷器时，窑内高温环境与低温瓷坯存在温度差，热量会通过热传导、热对流、热辐射等热传递的方式，从窑炉传递到瓷坯，进而改变瓷器胚体的内能。\nC项正确，氧化钴是一种金属氧化物，为黑灰色六方晶系粉末，不溶于水、醇、氨水，易被一氧化碳还原成金属钴，高温时易与二氧化硅、氧化铝或氧化锌反应生成多种颜料。青花瓷含有氧化钴的颜料，在img/formula-d20b36e613fcebf9.webp高温下与釉料成分反应，生成钴铝尖晶石等稳定化合物，借助二价钴离子的电子跃迁反射蓝光，形成稳定蓝色着色剂。\nD项正确，青花是瓷器釉彩之一，被用作白地蓝花瓷的专称。因蓝花在釉下，所以青花属“釉下彩”。其原料为含氧化钴的钴土矿，以蓝青色料在瓷胎上描绘纹饰，然后施透明釉，在高温还原焰中一次烧成。\n本题为选非题，故正确答案为A。",
   "exam": "tianjin",
   "year": 2026
