   "answer": "A",
   "analysis": "本题考查法律常识。《公务员法》第二条第二款：“本法所称公务员，是指依法履行公职、纳入国家行政编制、由国家财政负担工资福利的工作人员。”根据《公务员法释义》对本条的释义，是否属于公务员，必须符合三个条件：\n一是依法履行公职。即依法从事公务活动的人员，他不是为自己工作，也不是为某个私人的企业或者组织工作或者服务，故A选项正确。\n二是纳入国家行政编制。有一些非行政编制的工作人员，例如法院法官等，也属于公务员，故B选项错误。\n三是由国家财政负担工资福利。公务员属于国家财政供养的人员，但并不是财政供养的人员都是公务员。财政供养人员的很大一部分，如公立学校的老师、科研院所的科研人员等，虽然由国家负担其工资福利，但不属于公务员，故C选项错误。\n故正确答案为A。",
   "exam": "tianjin",
   "year": 2018
