   "analysis": "本题考查法律常识。\n公务员行为规范，从广义上讲，是指公务员的言谈举止在任何时候、任何场合都要进行一定的约束和限制。从狭义上讲，是指公务员在公务活动中必须自觉遵守和遵循的各项基本准则和纪律，包括政治思想、工作作风、办事规则、行政程序等等。\n出处：公共管理系列教材 《国家公务员制度教程》（舒放 王克良 主编），中国人民大学出版社 2001年第1版。\n故正确答案为D。",
   "exam": "tianjin",
   "year": 2018
